parameters.text:
=Analyze the SAHLA Box environment and output the state for ALL actuators.

ENVIRONMENTAL CONTEXT:
- Mode: {{ $json.meta.mode }}
- Crop: {{ $json.crop.type }} ({{ $json.crop.growth_stage }} stage)
- Current Time: {{ $json.sensors.time_of_day }}
- Soil Moisture: {{ $json.sensors.soil_moisture }}%
- Temperature: {{ $json.sensors.temperature }}°C
- Air Humidity: {{ $json.sensors.air_humidity }}%
- Luminosity: {{ $json.sensors.luminosity }} lux

ACTUATORS CURRENT STATE:
[PUMP]
- Skipped: {{ $json.actuators.pump.skipped }}
- Current physical_state: {{ $json.actuators.pump.physical_state }}
- Current timer.active: {{ $json.actuators.pump.timer.active }}
- Current timer.duration_minutes: {{ $json.actuators.pump.timer.duration_minutes }}

[FAN]
- Skipped: {{ $json.actuators.fan.skipped }}
- Current physical_state: {{ $json.actuators.fan.physical_state }}
- Current timer.active: {{ $json.actuators.fan.timer.active }}
- Current timer.duration_minutes: {{ $json.actuators.fan.timer.duration_minutes }}

INSTRUCTIONS:
1. You MUST output the state for BOTH the pump and the fan in a single line.
2. If an actuator has "Skipped: true", DO NOT change its values. Exactly copy its "Current" values to your output.
3. If an actuator has "Skipped: false", calculate its NEW values based on the environment and Mode.
4. Calculate 'timer.execute_until' (HH:MM format) by adding 'timer.duration_minutes' to the Current Time ({{ $json.sensors.time_of_day }}). If duration is null, execute_until is null.
5. Output EXACTLY following the structure below. Do not add any conversational text.

OUTPUT FORMAT:
pump.physical_state:<value> pump.timer.active:<value> pump.timer.duration_minutes:<value> pump.timer.execute_until:<value> fan.physical_state:<value> fan.timer.active:<value> fan.timer.duration_minutes:<value> fan.timer.execute_until:<value>

OUTPUT:

parameters.jsCode:
const originalData = $('Filter').first().json; 
let updatedData = JSON.parse(JSON.stringify(originalData));
const aiOutput = $input.first().json.output;

if (aiOutput) {
  const pairs = aiOutput.trim().split(/\s+/);

  for (let pair of pairs) {
    const colonIndex = pair.indexOf(':');
    if (colonIndex === -1) continue; 
    const path = pair.substring(0, colonIndex);
    let value = pair.substring(colonIndex + 1);

    if (value === 'true') {
        value = true;
    } else if (value === 'false') {
        value = false;
    } else if (value === 'null') {
        value = null;
    } else if (!isNaN(value) && value.trim() !== '') {
        value = Number(value); 
    }

    const keys = path.split('.');
    let currentLevel = updatedData.actuators;

    for (let i = 0; i < keys.length - 1; i++) {
      if (currentLevel[keys[i]] === undefined) {
         currentLevel[keys[i]] = {}; 
      }
      currentLevel = currentLevel[keys[i]];
    }

    currentLevel[keys[keys.length - 1]] = value;
  }
}

return [{ json: updatedData }];
